(()=>{
const names=['빈칸','씨앗 주머니','새싹 화분','싱싱한 채소','수확 바구니','나눔 상자'];
// Original vector pieces, drawn for this game; no third-party asset dependency.
const leaves='<path d="M49 54C15 52 10 17 22 15C42 10 51 34 49 54Z" fill="#8dbd50"/><path d="M49 53C49 22 71 12 81 19C88 35 71 54 49 53Z" fill="#4c9855"/><path d="M49 66V39" stroke="#347344" stroke-width="5"/>';
const pictures=[ '', '<path d="M35 27L29 12L43 17L55 10L69 16L64 29C85 45 90 76 70 84H31C9 74 18 44 35 27Z" fill="#d7ae69"/><path d="M34 28L66 28M29 74Q47 83 74 72" stroke="#af7d42" stroke-width="5"/><ellipse cx="49" cy="55" rx="10" ry="15" fill="#9c643e" transform="rotate(30 49 55)"/><path d="M48 45L44 62" stroke="#dfc293" stroke-width="3"/>', leaves+'<path d="M29 57H71L65 86H35Z" fill="#d89165"/><rect x="25" y="55" width="50" height="10" rx="4" fill="#e8ac7a"/>', '<path d="M50 86C16 87 5 62 17 44C9 24 29 11 43 24C53 6 73 16 75 30C98 34 88 66 73 70C72 84 60 89 50 86Z" fill="#70ae48"/><path d="M48 83C25 61 28 42 42 37C42 20 63 25 66 42C83 49 66 71 48 83Z" fill="#acd465"/><path d="M49 81L52 46M49 66L38 54M51 59L62 47" stroke="#e0ec94" stroke-width="4"/>', '<path d="M25 52C20 3 80 3 75 52" fill="none" stroke="#a36e42" stroke-width="8"/><path d="M19 50L31 32L45 48L56 25L72 46L81 33L83 59Z" fill="#77a54c"/><circle cx="35" cy="48" r="12" fill="#df7055"/><circle cx="65" cy="48" r="12" fill="#e5bb51"/><path d="M15 50H85L77 87H23Z" fill="#d4a365"/><path d="M19 62H81M22 75H79M35 52L39 85M53 52V86M71 52L67 85" stroke="#ad7d46" stroke-width="3"/>', '<rect x="17" y="39" width="66" height="48" rx="5" fill="#e5b36d"/><rect x="12" y="31" width="76" height="16" rx="5" fill="#f2ce8c"/><path d="M45 32V87H57V32" fill="#799c60"/><path d="M50 32C18 34 18 6 35 12C44 15 50 32 50 32ZM51 32C81 32 82 8 68 12C59 14 51 32 51 32Z" fill="#8fb571"/><path d="M37 65C31 55 42 51 49 59C58 49 69 57 61 65L49 77Z" fill="#fff4d9"/>' ];
const art=v=>v?`<svg viewBox="0 0 100 100" aria-hidden="true" class="merge-piece"><ellipse cx="50" cy="88" rx="34" ry="5" fill="#76593220"/><g stroke-linecap="round" stroke-linejoin="round">${pictures[v]}</g></svg>`:'<span class="merge-empty" aria-hidden="true">＋</span>';
let selected=-1,busy=false,message='',popped=-1,drag=null,suppressClick=0,restart=false;
const dialog=document.createElement('dialog');dialog.className='merge-game';dialog.setAttribute('aria-label','나눔 농장 머지 놀이터');document.body.append(dialog);
const menu=document.createElement('button');menu.textContent='🧺 나눔 농장 · 머지 놀이터';(document.querySelector('#compactQuiz')||document.querySelector('.compact-menu-grid')).append(menu);menu.onclick=()=>window.openMergeGame();
function draw(){const g=state.mergeGame;dialog.innerHTML=`<div class="merge-heading"><div><small>SHINY VILLAGE · 작은 쉼터</small><h2>나눔 농장</h2></div><button data-merge-close aria-label="놀이터 닫기">×</button></div><p class="merge-instruction">같은 물건을 끌어 합쳐요. 두 번 눌러도 돼요!</p><div class="merge-chain" aria-label="성장 순서">${[1,2,3,4,5].map((v,i)=>`${i?'<span>›</span>':''}<div title="${names[v]}">${art(v)}<small>${['','씨앗','새싹','채소','바구니','나눔'][v]}</small></div>`).join('')}</div>${!window.classroomActive?'<p>체험 학생 또는 학급으로 입장하면 놀이를 저장할 수 있어요.</p><button data-merge-entry>체험·학급 입장</button>':g?`<div class="merge-board" aria-label="물건을 합치는 4 곱하기 4 놀이판">${g.board.map((v,i)=>`<button data-merge-cell="${i}" class="${v?'filled':''} ${popped===i?'merge-pop':''}" aria-label="${i+1}번 ${names[v]}" aria-pressed="${selected===i}" ${busy||g.complete?'disabled':''}>${art(v)}${v?`<span class="merge-level">${v}</span>`:''}</button>`).join('')}</div><div class="merge-progress"><span>${g.complete?'🎉 나눔 상자 완성!':`${g.moves}번 합쳤어요`}</span><b>${g.complete?(g.reward?'+10 코인':'오늘 보너스 수령 완료'):'목표: 나눔 상자 1개'}</b></div><p role="status" class="merge-message">${escapeHtml(message|| (g.complete?'물건을 모아 이웃에게 전할 상자가 되었어요!':selected<0?'같은 물건끼리 합치면 한 단계 자라요.':'같은 물건 또는 빈칸을 골라 주세요.'))}</p><div class="merge-actions"><button data-merge-hint ${busy||g.complete?'disabled':''}>같은 물건 찾기</button><button data-merge-start ${busy?'disabled':''}>${g.complete?'한 판 더':restart?'정말 새로 시작':'새 판'}</button></div>`:`<div class="merge-welcome">${art(5)}<b>작은 씨앗을 모아 큰 나눔으로</b><p>시간 제한 없이 천천히 합쳐 보세요.</p><button data-merge-start>놀이 시작</button></div>`}<small class="merge-reward-note">하루 첫 완성 10코인 · 한국 날짜 기준<br>농장 재고는 사용하지 않아요. 닫아도 놀이판은 저장돼요.</small>`}
async function act(payload){if(busy)return;busy=true;message='저장 중…';draw();try{const ok=await schoolAction(payload);message=ok?'':'저장을 확인하지 못했어요. 연결과 수업 상태를 확인해 주세요.';if(ok){selected=-1;popped=payload.to??-1;restart=false}}finally{busy=false;draw();popped=-1}}
function choose(i){const g=state.mergeGame;if(!g||g.complete||busy)return;if(selected<0){if(!g.board[i]){message='먼저 옮길 물건을 골라 주세요.'}else{selected=i;message=''}}else if(selected===i){selected=-1;message=''}else if(!g.board[i]||g.board[selected]===g.board[i]){act({action:'merge_move',gameId:g.id,from:selected,to:i});return}else{selected=i;message='같은 물건끼리 합칠 수 있어요.'}draw()}
function cleanup(){drag?.ghost?.remove();dialog.querySelector('.merge-drag-source')?.classList.remove('merge-drag-source');dialog.querySelectorAll('.merge-drop-target').forEach(b=>b.classList.remove('merge-drop-target'));drag=null}
window.openMergeGame=()=>{document.querySelector('.compact-menu')?.close();cleanup();selected=-1;restart=false;message='';draw();if(!dialog.open)dialog.showModal()};
dialog.addEventListener('pointerdown',e=>{const cell=e.target.closest('[data-merge-cell]'),g=state.mergeGame;if(!cell||busy||!e.isPrimary||e.button!==0||!g||g.complete)return;const i=Number(cell.dataset.mergeCell);if(!g.board[i])return;drag={from:i,value:g.board[i],gameId:g.id,x:e.clientX,y:e.clientY,id:e.pointerId,cell};cell.setPointerCapture(e.pointerId)});
dialog.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;if(!drag.ghost&&Math.hypot(e.clientX-drag.x,e.clientY-drag.y)<6)return;if(!drag.ghost){const ghost=document.createElement('div');ghost.className='merge-drag-ghost';ghost.innerHTML=art(drag.value);dialog.append(ghost);drag.ghost=ghost;drag.cell.classList.add('merge-drag-source')}e.preventDefault();drag.ghost.style.left=e.clientX+'px';drag.ghost.style.top=e.clientY+'px';dialog.querySelectorAll('.merge-drop-target').forEach(b=>b.classList.remove('merge-drop-target'));const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-merge-cell]');if(target&&Number(target.dataset.mergeCell)!==drag.from){const v=state.mergeGame.board[Number(target.dataset.mergeCell)];if(!v||v===drag.value)target.classList.add('merge-drop-target')}});
dialog.addEventListener('pointerup',e=>{if(!drag||e.pointerId!==drag.id)return;const old=drag,target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-merge-cell]');cleanup();if(!old.ghost)return;suppressClick=Date.now()+400;e.preventDefault();const g=state.mergeGame;if(!target||g.id!==old.gameId)return;const to=Number(target.dataset.mergeCell);if(to===old.from)return;if(g.board[to]&&g.board[to]!==old.value){message='다른 물건이에요. 같은 그림 위에 놓아 주세요.';draw();return}act({action:'merge_move',gameId:old.gameId,from:old.from,to})});
dialog.addEventListener('pointercancel',cleanup);dialog.addEventListener('close',cleanup);
dialog.onclick=e=>{if(Date.now()<suppressClick)return;const b=e.target.closest('button');if(!b||busy)return;if(b.hasAttribute('data-merge-close')){dialog.close();return}if(b.hasAttribute('data-merge-entry')){dialog.close();entrySchool();return}if(b.hasAttribute('data-merge-start')){const g=state.mergeGame;if(g&&!g.complete&&!restart){restart=true;message='새 판을 시작하면 현재 놀이판이 초기화돼요. 한 번 더 누르면 시작합니다.';draw();return}selected=-1;act({action:'merge_start'});return}if(b.hasAttribute('data-merge-hint')){const g=state.mergeGame;for(let i=0;i<16;i++)for(let j=i+1;j<16;j++)if(g.board[i]&&g.board[i]===g.board[j]){selected=i;message=`${i+1}번과 ${j+1}번 ${names[g.board[i]]}를 합쳐 보세요.`;draw();return}}if(b.dataset.mergeCell!==undefined)choose(Number(b.dataset.mergeCell))};
})();
